mapper.update:
update account
set account_block = #{accountBlock}
where account_id = #{accountId}

mapper.select:
select account_id, account_nickname, account_email, account_birth, account_contact, account_post, account_address1, account_address2, account_join, account_login, account_change, account_level, account_point, account_block from account
and account_id = #{accountId}
and account_nickname = #{accountNickname}
and account_contact = #{accountContact}
and instr(account_email, #{accountEmail}) > 0
and ( instr(account_post, #{accountAddress}) > 0 or instr(account_address1, #{accountAddress}) > 0 or instr(account_address2, #{accountAddress}) > 0 )
and to_TIMESTAMP(account_birth, 'YYYY-MM-DD') between to_timestamp(#{accountBirthBegin}, 'YYYY-MM-DD') and to_timestamp(#{accountBirthEnd}, 'YYYY-MM-DD')
and account_birth >= to_timestamp(#{accountBirthBegin}, 'YYYY-MM-DD')
and account_birth <= to_timestamp(#{accountBirthEnd}, 'YYYY-MM-DD')
and account_join between to_timestamp(#{accountJoinBegin} || ' ' || '00:00:00.000', 'YYYY-MM-DD HH24:MI:FF3') and to_timestamp(#{accountJoinEnd} || ' ' || '00:00:00.000', 'YYYY-MM-DD HH24:MI:FF3')
and account_join >= to_timestamp(#{accountJoinBegin} || ' ' || '00:00:00.000', 'YYYY-MM-DD HH24:MI:FF3')
and account_join < to_timestamp(#{accountJoinEnd} || ' ' || '00:00:00.000', 'YYYY-MM-DD HH24:MI:FF3')
and account_login between to_timestamp(#{accountLoginBegin} || ' ' || '00:00:00.000', 'YYYY-MM-DD HH24:MI:FF3') and to_timestamp(#{accountLoginEnd} || ' ' || '00:00:00.000', 'YYYY-MM-DD HH24:MI:FF3')
and account_login >= to_timestamp(#{accountLoginBegin} || ' ' || '00:00:00.000', 'YYYY-MM-DD HH24:MI:FF3')
and account_login < to_timestamp(#{accountLoginEnd} || ' ' || '00:00:00.000', 'YYYY-MM-DD HH24:MI:FF3')
and account_level in
#{accountLevel}
and account_block = #{accountBlock}
and account_point between #{accountPointMin} and #{accountPointMax}
and account_point >= #{accountPointMin}
and account_point <= #{accountPointMax}
select * from ( select * from temp_list
where rn > (
select rn from temp_list where account_id = #{lastAccountId} )
)
where rownum <= #{size}

select account_id, account_nickname, account_email, account_birth, account_contact, account_post, account_address1, account_address2, account_join, account_login, account_change, account_level, account_point, account_block from account
and account_id = #{accountId}
and account_nickname = #{accountNickname}
and account_contact = #{accountContact}
and instr(account_email, #{accountEmail}) > 0
and ( instr(account_post, #{accountAddress}) > 0 or instr(account_address1, #{accountAddress}) > 0 or instr(account_address2, #{accountAddress}) > 0 )
and to_TIMESTAMP(account_birth, 'YYYY-MM-DD') between to_timestamp(#{accountBirthBegin}, 'YYYY-MM-DD') and to_timestamp(#{accountBirthEnd}, 'YYYY-MM-DD')
and account_birth >= to_timestamp(#{accountBirthBegin}, 'YYYY-MM-DD')
and account_birth <= to_timestamp(#{accountBirthEnd}, 'YYYY-MM-DD')
and account_join between to_timestamp(#{accountJoinBegin} || ' ' || '00:00:00.000', 'YYYY-MM-DD HH24:MI:FF3') and to_timestamp(#{accountJoinEnd} || ' ' || '00:00:00.000', 'YYYY-MM-DD HH24:MI:FF3')
and account_join >= to_timestamp(#{accountJoinBegin} || ' ' || '00:00:00.000', 'YYYY-MM-DD HH24:MI:FF3')
and account_join < to_timestamp(#{accountJoinEnd} || ' ' || '00:00:00.000', 'YYYY-MM-DD HH24:MI:FF3')
and account_login between to_timestamp(#{accountLoginBegin} || ' ' || '00:00:00.000', 'YYYY-MM-DD HH24:MI:FF3') and to_timestamp(#{accountLoginEnd} || ' ' || '00:00:00.000', 'YYYY-MM-DD HH24:MI:FF3')
and account_login >= to_timestamp(#{accountLoginBegin} || ' ' || '00:00:00.000', 'YYYY-MM-DD HH24:MI:FF3')
and account_login < to_timestamp(#{accountLoginEnd} || ' ' || '00:00:00.000', 'YYYY-MM-DD HH24:MI:FF3')
and account_level in
#{accountLevel}
and account_block = #{accountBlock}
and account_point between #{accountPointMin} and #{accountPointMax}
and account_point >= #{accountPointMin}
and account_point <= #{accountPointMax}
select count(*) from ( select * from temp_list
where rn > (
select rn from temp_list where account_id = #{lastAccountId} )
)
